-- official_food_hs_code_import.sql
-- 來源：note_8_C.txt（中文貨名） + netrate_new.txt（一般稅率）
-- 範圍：食品相關章別 02,03,04,07,08,09,10,12,17,18,19,20,21
-- 匯入策略：只匯入『第一欄(優惠) 從價 %』可用的資料；從量稅資料請看 official_food_specific_duty_review.csv
-- 產生筆數：1866 筆；略過從量稅/非百分比資料：105 筆
USE import_tax_db;

START TRANSACTION;

INSERT INTO category(code, name, storage_type, description) VALUES
('DRY_GOODS', '乾貨', '常溫', '常溫保存，適合咖啡、米、麵、茶粉、零食等'),
('FRESH', '生鮮', '冷藏', '需冷藏保存，適合蔬菜水果等'),
('FROZEN', '冷凍', '冷凍', '需冷凍保存，適合冷凍海鮮或冷凍食品'),
('MEAT', '肉品', '冷藏 / 冷凍', '肉類商品'),
('SEAFOOD', '海鮮', '冷藏 / 冷凍', '魚類、水產與海鮮商品'),
('CHILLED', '冷藏', '冷藏', '乳製品等需冷藏商品'),
('SEASONING', '調味品', '常溫', '醬油、味噌、調味醬料等'),
('PROCESSED_FOOD', '加工食品', '常溫 / 冷藏', '調製食品、加工食品')

ON DUPLICATE KEY UPDATE name = VALUES(name), storage_type = VALUES(storage_type), description = VALUES(description);

